insert into public.promotions (id, store_id, code, title, conditions, actions, starts_at, ends_at, usage_limit, per_customer_limit, times_used, active, combinable)
  select id, '00000000-0000-4000-8000-000000000001', code, title, conditions, actions, "startsAt", "endsAt", "usageLimit", "perCustomerLimit", "timesUsed", active, combinable
  from jsonb_to_recordset($seed$[{"id":"70000000-0000-4000-8000-000000000001","storeId":"00000000-0000-4000-8000-000000000001","code":"WELCOME10","title":"10% off your first order","conditions":[{"type":"first_order"}],"actions":[{"type":"percent_off_order","basisPoints":1000}],"startsAt":null,"endsAt":null,"usageLimit":null,"perCustomerLimit":1,"timesUsed":0,"active":true,"combinable":false},{"id":"70000000-0000-4000-8000-000000000002","storeId":"00000000-0000-4000-8000-000000000001","code":"PRELOVED500","title":"Rs. 500 off pre-loved pairs over Rs. 10,000","conditions":[{"type":"product_kind","kind":"preloved"},{"type":"subtotal_at_least","amount":1000000}],"actions":[{"type":"fixed_off_order","amount":50000}],"startsAt":null,"endsAt":null,"usageLimit":500,"perCustomerLimit":null,"timesUsed":0,"active":true,"combinable":true}]$seed$::jsonb)
    as r(id uuid, code text, title text, conditions jsonb, actions jsonb, "startsAt" timestamptz, "endsAt" timestamptz, "usageLimit" integer, "perCustomerLimit" integer, "timesUsed" integer, active boolean, combinable boolean);

insert into public.feature_flags (store_id, key, description, enabled, customer_groups)
  select '00000000-0000-4000-8000-000000000001', key, description, enabled, array(select jsonb_array_elements_text("customerGroups"))
  from jsonb_to_recordset($seed$[{"key":"b2b-pricing","description":"Wholesale price list and quote requests for approved trade accounts.","enabled":false,"customerGroups":["wholesale"]},{"key":"multi-currency-display","description":"Show approximate prices in USD / AED / GBP next to PKR.","enabled":false,"customerGroups":null},{"key":"stripe-payments","description":"Card payments through Stripe (needs STRIPE_SECRET_KEY).","enabled":false,"customerGroups":null},{"key":"express-delivery","description":"Offer the express delivery rate at checkout.","enabled":true,"customerGroups":null}]$seed$::jsonb)
    as r(key text, description text, enabled boolean, "customerGroups" jsonb);

insert into public.pages (store_id, slug, title, description, blocks, seo, published, updated_at)
  select '00000000-0000-4000-8000-000000000001', slug, title, description, blocks, coalesce(seo, '{}'), true, "updatedAt"
  from jsonb_to_recordset($seed$[{"slug":"shipping","title":"Shipping","description":"Delivery times and costs across Pakistan.","updatedAt":"2026-11-03T00:00:00.000Z","seo":{},"blocks":[{"type":"paragraph","text":"We deliver across Pakistan with tracked courier partners. Orders placed before 3 PM on a working day leave our warehouse the same day."},{"type":"heading","text":"Delivery costs","level":2},{"type":"list","items":["Standard delivery (2–5 working days): Rs. 250","Free standard delivery on orders above PKR 5,000","Express delivery in Karachi, Lahore and Islamabad (1–2 working days): Rs. 600"]},{"type":"heading","text":"Cash on delivery","level":2},{"type":"paragraph","text":"Cash on delivery is available on every order. Please keep the exact amount ready for the rider."},{"type":"cta","text":"Questions about a delivery?","label":"Contact us","href":"/contact"}]},{"slug":"returns","title":"Returns","description":"Our 7-day return policy for new and pre-loved pairs.","updatedAt":"2026-11-03T00:00:00.000Z","seo":{},"blocks":[{"type":"paragraph","text":"You have 7 days from delivery to return a pair."},{"type":"heading","text":"Brand-new pairs","level":2},{"type":"list","items":["Unworn, with all tags and the original box","Refunds go back to your original payment method, or by bank transfer for cash-on-delivery orders","Return delivery is free if we sent the wrong pair or size"]},{"type":"heading","text":"Pre-loved pairs","level":2},{"type":"paragraph","text":"Pre-loved pairs can be returned if they don't match the condition described on the listing."},{"type":"heading","text":"How to return","level":2},{"type":"list","ordered":true,"items":["Open your order from Account → Orders or your confirmation email","Choose Request a return and tell us why","We'll arrange a pickup and refund you once the pair reaches us"]}]},{"slug":"privacy-policy","title":"Privacy Policy","description":"How Sole Drop collects and uses your personal data.","updatedAt":"2026-11-03T00:00:00.000Z","seo":{},"blocks":[{"type":"callout","title":"Draft for the owner's review","text":"This policy describes what the store software actually does. Have it reviewed before launch."},{"type":"heading","text":"What we collect","level":2},{"type":"list","items":["Order details: name, phone, email and delivery address","Account details if you create one: email and a securely hashed password","Newsletter sign-ups: your email address and when you agreed","Messages you send through the contact form"]},{"type":"heading","text":"How we use it","level":2},{"type":"paragraph","text":"Only to deliver your order, provide customer service, and — if you subscribed — send you news about new drops. We never sell your data."},{"type":"heading","text":"Cookies","level":2},{"type":"paragraph","text":"We use strictly necessary cookies to keep your bag and sign-in working. We don't use advertising cookies."},{"type":"heading","text":"Your rights","level":2},{"type":"paragraph","text":"You can download or delete your account data from Account → Privacy, unsubscribe from any email, or contact us to correct your details."}]},{"slug":"terms","title":"Terms of Sale","description":"The terms that apply when you buy from Sole Drop.","updatedAt":"2026-11-03T00:00:00.000Z","seo":{},"blocks":[{"type":"callout","title":"Draft for the owner's review","text":"Have these terms reviewed before launch."},{"type":"paragraph","text":"Prices are in Pakistani rupees and include GST. An order is a contract once we confirm it by email. We may cancel an order if a pair is no longer available, in which case any payment is refunded in full."}]},{"slug":"about","title":"About Sole Drop","description":"New and pre-loved footwear from brands you love.","updatedAt":"2026-11-03T00:00:00.000Z","seo":{},"blocks":[{"type":"paragraph","text":"Sole Drop sells brand-new and pre-loved footwear from the brands you love — ASICS, Nike, adidas, HOKA, Brooks and more."},{"type":"paragraph","text":"Every brand-new pair is sourced from authorised distributors. Every pre-loved pair is inspected, cleaned, graded and photographed, so the pair you see is the pair you get."},{"type":"cta","text":"Fresh finds. Fresh steps.","label":"Shop new arrivals","href":"/collections/new-arrivals"}]},{"slug":"our-story","title":"Our Story","description":"Why we started Sole Drop.","updatedAt":"2026-11-03T00:00:00.000Z","seo":{},"blocks":[{"type":"paragraph","text":"Sole Drop started in Karachi with a simple idea: great shoes shouldn't be hard to find, and good shoes shouldn't go to waste."},{"type":"paragraph","text":"So we built one place for new releases and second-chance pairs — honest about condition, quick to deliver, and easy to return."}]}]$seed$::jsonb) as r(slug text, title text, description text, blocks jsonb, seo jsonb, "updatedAt" timestamptz);

insert into public.faqs (id, store_id, category, question, answer, position)
  select id, '00000000-0000-4000-8000-000000000001', category, question, answer, position
  from jsonb_to_recordset($seed$[{"id":"80000000-0000-4000-8000-000000000001","category":"Orders & payment","question":"How do I place an order?","answer":"Pick your size, add the pair to your bag and check out. You don't need an account — we'll email your order confirmation and you can track it from the link inside.","position":0},{"id":"80000000-0000-4000-8000-000000000002","category":"Orders & payment","question":"Which payment methods do you accept?","answer":"Cash on delivery anywhere in Pakistan, and bank transfer. For bank transfer we show our account details after you place the order; we ship once the payment lands.","position":1},{"id":"80000000-0000-4000-8000-000000000003","category":"Orders & payment","question":"Can I change or cancel my order?","answer":"Yes, until it ships. Message us on WhatsApp or through the contact form with your order number and we'll update or cancel it.","position":2},{"id":"80000000-0000-4000-8000-000000000004","category":"Delivery","question":"How much is delivery?","answer":"Standard delivery is Rs. 250 and free on orders above PKR 5,000.","position":3},{"id":"80000000-0000-4000-8000-000000000005","category":"Delivery","question":"How long will my order take?","answer":"2–5 working days for standard delivery across Pakistan, 1–2 days for express delivery in Karachi, Lahore and Islamabad.","position":4},{"id":"80000000-0000-4000-8000-000000000006","category":"Delivery","question":"How do I track my order?","answer":"Once your order ships we email a tracking number. You can also see the status any time from Account → Orders or the link in your confirmation email.","position":5},{"id":"80000000-0000-4000-8000-000000000007","category":"Returns & exchanges","question":"What is your return policy?","answer":"Brand-new pairs can be returned within 7 days of delivery if they're unworn and in the original box. Start a return from your order page or contact us.","position":6},{"id":"80000000-0000-4000-8000-000000000008","category":"Returns & exchanges","question":"Can I exchange for a different size?","answer":"Yes. Request a return for the pair and place a new order for the size you need — we'll refund the first pair as soon as it reaches us.","position":7},{"id":"80000000-0000-4000-8000-000000000009","category":"Returns & exchanges","question":"Can I return a pre-loved pair?","answer":"Pre-loved pairs can be returned within 7 days if they don't match the condition we described. Each listing shows the exact pair you'll receive.","position":8},{"id":"80000000-0000-4000-8000-000000000010","category":"Pre-loved","question":"What does the condition grade mean?","answer":"Like New: looks almost brand new, very clean from top to bottom. Excellent: worn a little, but still very clean and in great shape. Great: used, but well looked after. Good: shows more use, but still looks good and feels fine to wear. Minor Marks: may have small marks or flaws, always shown in the photos. Every pair is inspected, cleaned and sanitised.","position":9},{"id":"80000000-0000-4000-8000-000000000011","category":"Pre-loved","question":"Are pre-loved pairs authentic?","answer":"Yes. Every pair is checked by our team before it's listed. If a pair ever turns out not to be authentic, you get a full refund.","position":10},{"id":"80000000-0000-4000-8000-000000000012","category":"Sizing","question":"How do I find my size?","answer":"Use our size guide to convert between EU, UK, US and CM. If you're between two sizes, choose the larger one for a roomier fit.","position":11}]$seed$::jsonb) as r(id uuid, category text, question text, answer text, position integer);

insert into public.search_synonyms (id, store_id, term, synonyms)
  select id, '00000000-0000-4000-8000-000000000001', term, array(select jsonb_array_elements_text(synonyms))
  from jsonb_to_recordset($seed$[{"id":"60000000-0000-4000-8000-000000000001","term":"sneakers","synonyms":["trainers","kicks","joggers"]},{"id":"60000000-0000-4000-8000-000000000002","term":"running","synonyms":["runners","jogging"]},{"id":"60000000-0000-4000-8000-000000000003","term":"pre-loved","synonyms":["preloved","used","second hand","thrift"]},{"id":"60000000-0000-4000-8000-000000000004","term":"new balance","synonyms":["nb"]},{"id":"60000000-0000-4000-8000-000000000005","term":"grey","synonyms":["gray"]},{"id":"60000000-0000-4000-8000-000000000006","term":"sketchers","synonyms":["skechers"]}]$seed$::jsonb) as r(id uuid, term text, synonyms jsonb);
